/** Generates a complete, valid .env for local development: `npm run gen:env > .env` */
import { generateKeyPairSync, randomBytes } from 'node:crypto';

const b64 = (b: Buffer | string) => Buffer.from(b).toString('base64');
const { privateKey, publicKey } = generateKeyPairSync('ec', { namedCurve: 'P-256' });
const lines = [
  '# Generated by `npm run gen:env`. DEV ONLY - never commit; production secrets come from the secret manager.',
  'NODE_ENV=development',
  'PORT=3000',
  'METRICS_PORT=9464',
  'LOG_LEVEL=info',
  'DATABASE_URL=postgres://postgres:postgres@localhost:5432/amrutam',
  'REDIS_URL=redis://localhost:6379',
  `JWT_PRIVATE_KEY_B64=${b64(privateKey.export({ type: 'pkcs8', format: 'pem' }) as string)}`,
  `JWT_PUBLIC_KEY_B64=${b64(publicKey.export({ type: 'spki', format: 'pem' }) as string)}`,
  'JWT_KEY_ID=k1',
  `DATA_KEYS_JSON=${JSON.stringify({ k1: b64(randomBytes(32)) })}`,
  'DATA_KEY_ACTIVE=k1',
  `BLIND_INDEX_KEY_B64=${b64(randomBytes(32))}`,
  `AUDIT_HMAC_KEY_B64=${b64(randomBytes(32))}`,
  `SIGNING_KEY_B64=${b64(randomBytes(32))}`,
  `PAYMENT_WEBHOOK_SECRET=${randomBytes(24).toString('hex')}`,
  'ENABLE_DEV_ENDPOINTS=true',
  'BOOKING_HOLD_SECONDS=600',
];
console.log(lines.join('\n'));
